"""Password hashing compatibility and backend initialization regressions."""
import subprocess
import sys
import unittest

from app.core.security import hash_password, verify_password


# Generated by the previous Passlib 1.7.4 implementation, using test passwords only.
LEGACY_HASH = "$2b$12$wAUgn0EzJ6G0sriM.aDzNe8Mzq7K48nKmhCy6TgcmS09dLCFB04jG"


class PasswordTests(unittest.TestCase):
    def test_password_operations_do_not_log_backend_errors_in_a_fresh_process(self):
        script = f"""
from app.core.security import hash_password, verify_password
assert verify_password('legacy-test-password', {LEGACY_HASH!r})
assert verify_password('new-test-password', hash_password('new-test-password'))
"""
        result = subprocess.run(
            [sys.executable, "-c", script], capture_output=True, text=True, check=True
        )
        self.assertEqual(result.stderr, "")

    def test_existing_passlib_hashes_accept_correct_passwords_only(self):
        fixtures = (
            ("legacy-test-password", LEGACY_HASH),
            (
                "兼容旧账号🔐",
                "$2b$12$e5K.LTZtQ9NH/gRwvfLR/u/RZLKxSiEh6Oi9.ztc8BjUlE3fpxNsq",
            ),
            (
                "密" * 25,
                "$2b$12$a/0naV.9MkkfTBrQlZ6D3uK88Y4NmT6pCKHCPWWuumQ4rfqlTh0BO",
            ),
        )
        for password, hashed in fixtures:
            with self.subTest(password=password):
                self.assertTrue(verify_password(password, hashed))
                self.assertFalse(verify_password("wrong-password", hashed))

    def test_legacy_bcrypt_prefixes_remain_supported(self):
        for prefix in ("$2a$", "$2y$"):
            with self.subTest(prefix=prefix):
                self.assertTrue(
                    verify_password("legacy-test-password", prefix + LEGACY_HASH[4:])
                )

    def test_new_unicode_passwords_use_salted_bcrypt_with_the_existing_cost(self):
        password = "新密码🔐-test"
        first = hash_password(password)
        second = hash_password(password)
        self.assertTrue(first.startswith("$2b$12$"))
        self.assertNotEqual(first, second)
        self.assertTrue(verify_password(password, first))
        self.assertFalse(verify_password("wrong-password", first))

    def test_null_bytes_remain_rejected(self):
        with self.assertRaises(ValueError):
            hash_password("test\x00password")
        with self.assertRaises(ValueError):
            verify_password("test\x00password", LEGACY_HASH)

    def test_passwords_exceeding_the_previous_byte_limit_remain_rejected(self):
        for password in ("a" * 4097, "密" * 1366):
            with self.subTest(byte_length=len(password.encode("utf-8"))):
                with self.assertRaises(ValueError):
                    hash_password(password)
                with self.assertRaises(ValueError):
                    verify_password(password, LEGACY_HASH)


if __name__ == "__main__":
    unittest.main()
